export function findVnProvinceByCode(code: string): VnProvince | undefined {
  return VN_PROVINCES.find((p) => p.code === code);
}

export function findVnProvinceByName(name: string): VnProvince | undefined {
  return VN_PROVINCES.find((p) => p.name === name || p.shortName === name);
}

export function findVnWardByName(province: VnProvince, name: string): VnWard | undefined {
  return province.wards.find((w) => w.name === name || w.shortName === name);
}
